pub fn register_workflow_host(rb_obj: magnus::Value, name: String) -> Result<(), magnus::Error> {
    let required_methods =
        ["descriptor", "execute_batch", "execute_typed_batch", "execute_detached_batch"];
    for method in &required_methods {
        if !rb_obj.respond_to(*method, false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Backend missing required method: {}", method),
            ));
        }
    }
    let wrapper = RbWorkflowHostBridge::new(rb_obj, name)?;
    let arc: Arc<dyn structuredmerge_host_prototype_core::WorkflowHost> = Arc::new(wrapper);

    structuredmerge_host_prototype_core::plugins::register_workflow_host(arc).map_err(|e| {
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        magnus::Error::new(ruby.exception_runtime_error(), format!("register failed: {}", e))
    })?;
    Ok(())
}

