#[magnus::init]
fn ruby_init(ruby: &Ruby) -> Result<(), Error> {
    let module = ruby.define_module("StructuredmergeHostPrototypeCore")?;

    // Ensure JSON library is loaded for Hash#to_json
    let _ = ruby.eval::<magnus::Value>("require \"json\"");

    let class = module.define_class("HostBatchRequest", ruby.class_object())?;

    class.define_singleton_method("new", function!(HostBatchRequest::new, -1))?;

    class.define_method("schema", method!(HostBatchRequest::schema, 0))?;

    class.define_method("items", method!(HostBatchRequest::items, 0))?;

    let class = module.define_class("HostPrototypeError", ruby.class_object())?;

    class.define_method("message", method!(HostPrototypeError::message, 0))?;

    let class = module.define_class("HostSourceSegment", ruby.class_object())?;

    class.define_singleton_method("new", function!(HostSourceSegment::new, -1))?;

    class.define_method("source_id", method!(HostSourceSegment::source_id, 0))?;

    class.define_method("offset", method!(HostSourceSegment::offset, 0))?;

    class.define_method("byte_length", method!(HostSourceSegment::byte_length, 0))?;

    class.define_method("sha256", method!(HostSourceSegment::sha256, 0))?;

    module.define_module_function(
        "execute_detached_identity",
        function!(execute_detached_identity, 5),
    )?;

    module.define_module_function("execute_identity", function!(execute_identity, 2))?;

    module.define_module_function(
        "execute_in_process_identity",
        function!(execute_in_process_identity, 4),
    )?;

    module
        .define_module_function("execute_typed_identity", function!(execute_typed_identity, 5))?;

    module.define_module_function("parse_with_parser", function!(parse_with_parser, 2))?;

    module.define_module_function("poll_identity_worker", function!(poll_identity_worker, 1))?;

    module.define_module_function("probe_with_parser", function!(probe_with_parser, 2))?;

    module
        .define_module_function("registered_parser_hosts", function!(registered_parser_hosts, 0))?;

    module.define_module_function(
        "registered_workflow_hosts",
        function!(registered_workflow_hosts, 0),
    )?;

    module.define_module_function("start_identity_worker", function!(start_identity_worker, 2))?;

    module
        .define_module_function("register_workflow_host", function!(register_workflow_host, 2))?;

    module.define_module_function(
        "unregister_workflow_host",
        function!(unregister_workflow_host, 1),
    )?;

    module.define_module_function("clear_workflow_hosts", function!(clear_workflow_hosts, 0))?;

    module.define_module_function("register_parser_host", function!(register_parser_host, 2))?;

    module
        .define_module_function("unregister_parser_host", function!(unregister_parser_host, 1))?;

    module.define_module_function("clear_parser_hosts", function!(clear_parser_hosts, 0))?;

    Ok(())
}
